Database: concert_singer
Schema:
CREATE TABLE stadium (Stadium_ID int PRIMARY KEY, Location text, Name text, Capacity int, Highest int, Lowest int, Average int);
CREATE TABLE singer (Singer_ID int PRIMARY KEY, Name text, Country text, Song_Name text, Song_release_year text, Age int, Is_male bool);
CREATE TABLE concert (concert_ID int PRIMARY KEY, concert_Name text, Theme text, Stadium_ID text, Year text, FOREIGN KEY (Stadium_ID) REFERENCES stadium(Stadium_ID));
CREATE TABLE singer_in_concert (concert_ID int, Singer_ID text, PRIMARY KEY (concert_ID,Singer_ID));
Question: Show name, country, age for all singers in descending order of age.
Target SQL: SELECT Name, Country, Age FROM singer ORDER BY Age DESC

